} for entry in [{"key": k, "value": v} for k, v in sorted(cluster_addons.items())]])
```
```csharp
using System.Collections.Generic;
using System.Linq;
using Pulumi;
using AliCloud = Pulumi.AliCloud;
using Std = Pulumi.Std;

return await Deployment.RunAsync(() => 
{
    var k8s = new AliCloud.CS.ManagedKubernetes("k8s", new()
    {
        Addons = .Select(entry => 
        {
            return new AliCloud.CS.Inputs.ManagedKubernetesAddonArgs
            {
                Name = Output.Create(Std.Lookup.Invoke(new()
                {
                    Map = entry.Value,
                    Key = "name",
                    Default = clusterAddons,
                }).Apply(invoke => invoke.Result)).Apply(x => x.ToString(System.Globalization.CultureInfo.InvariantCulture)),
                Config = Output.Create(Std.Lookup.Invoke(new()
                {
                    Map = entry.Value,
                    Key = "config",
                    Default = clusterAddons,
                }).Apply(invoke => invoke.Result)).Apply(x => x.ToString(System.Globalization.CultureInfo.InvariantCulture)),
                Version = Output.Create(Std.Lookup.Invoke(new()
                {
                    Map = entry.Value,
                    Key = "version",
                    Default = clusterAddons,
                }).Apply(invoke => invoke.Result)).Apply(x => x.ToString(System.Globalization.CultureInfo.InvariantCulture)),
                Disabled = Output.Create(Std.Lookup.Invoke(new()
                {
                    Map = entry.Value,
                    Key = "disabled",
                    Default = clusterAddons,
                }).Apply(invoke => invoke.Result)).Apply(x => x == "true"),
            };
        }).ToList(),
    });

});
```
