    alicloud = {
      source = "pulumi/alicloud"
    }
    std = {
      source = "pulumi/std"
    }
  }
}

data "std_format" "invoke_0" {
  count = 2
  input = "10.4.%d.0/24"
  args  = [count.index + 1]
}
data "std_format" "invoke_1" {
  count = 2
  input ="${var.name}_%d"
  args  = [count.index + 1]
}
data "alicloud_alb_zones" "default" {
}
data "alicloud_resourcemanager_resource_groups" "defaultGetResourceGroups" {
}
