  availability_zone = data.alicloud_alb_zones.default.zones[0].id
  cpu_core_count    = 1
  memory_size       = 2
}
data "alicloud_ecs_images" "defaultGetImages" {
  name_regex = "^ubuntu_18.*64"
  owners     = "system"
}

resource "alicloud_vpc_network" "default" {
  lifecycle {
    create_before_destroy = true
  }
  vpc_name   = var.name
  cidr_block = "10.4.0.0/16"
}
resource "alicloud_vpc_switch" "default" {
  count = 2
  pulumi {
    name ="default-${count.index}"
  }
  lifecycle {
    create_before_destroy = true
  }
  vpc_id       = alicloud_vpc_network.default.id
  cidr_block   = data.std_format.invoke_0[count.index].result
