    defaultSwitch.push(new alicloud.vpc.Switch(`default-${range}`, {
        vpcId: defaultNetwork.id,
        cidrBlock: std.format({
            input: "10.4.%d.0/24",
            args: [range + 1],
        }).then(invoke => invoke.result),
        zoneId: _default.then(_default => _default.zones[range].id),
        vswitchName: std.format({
            input: `${name}_%d`,
            args: [range + 1],
        }).then(invoke => invoke.result),
    }));
}
