			VswitchName: pulumi.Sprintf("%v-vsw", name),
			VpcId:       _default.ID(),
			ZoneId:      pulumi.String("cn-hangzhou-b"),
			CidrBlock:   pulumi.String("192.168.15.0/24"),
		})
		if err != nil {
			return err
		}
		defaultGateway, err := apig.NewGateway(ctx, "default", &apig.GatewayArgs{
			GatewayName: pulumi.Sprintf("%v-gw", name),
			GatewayType: pulumi.String("API"),
			PaymentType: pulumi.String("PayAsYouGo"),
			Spec:        pulumi.String("apigw.small.x1"),
			NetworkAccessConfig: &apig.GatewayNetworkAccessConfigArgs{
				Type: pulumi.String("Intranet"),
