import * as pulumi from "@pulumi/pulumi";
import * as alicloud from "@pulumi/alicloud";

const config = new pulumi.Config();
const name = config.get("name") || "terraform-example";
const _default = alicloud.vpc.getNetworks({
    nameRegex: "^default-NODELETING$",
});
const defaultGetSwitches = _default.then(_default => alicloud.vpc.getSwitches({
    vpcId: _default.ids?.[0],
    zoneId: "cn-hangzhou-j",
}));
const defaultInstance = new alicloud.kms.Instance("default", {
    productVersion: "3",
    vpcNum: 1,
    keyNum: 1000,
    secretNum: 1000,
    spec: 1000,
    vpcId: _default.then(_default => _default.ids?.[0]),
    vswitchIds: [defaultGetSwitches.then(defaultGetSwitches => defaultGetSwitches.ids?.[0])],
    zoneIds: [
        "cn-hangzhou-k",
        "cn-hangzhou-j",
    ],
});
const defaultKey = new alicloud.kms.Key("default", {
    dkmsInstanceId: defaultInstance.id,
    pendingWindowInDays: 7,
});
const defaultSecret = new alicloud.kms.Secret("default", {
    secretData: name,
    secretName: name,
    versionId: "v1",
    dkmsInstanceId: defaultKey.dkmsInstanceId,
    encryptionKeyId: defaultKey.id,
    forceDeleteWithoutRecovery: true,
});
const defaultSecret2 = new alicloud.apig.Secret("default", {
    gatewayType: "API",
    name: name,
    secretSource: "KMS",
    secretData: defaultSecret.secretData,
    kmsConfig: {
        kmsInstanceId: defaultSecret.dkmsInstanceId,
        kmsKeyId: defaultSecret.encryptionKeyId,
    },
});
