package main

import (
	"github.com/pulumi/pulumi-alicloud/sdk/v4/go/alicloud/apig"
	"github.com/pulumi/pulumi-alicloud/sdk/v4/go/alicloud/kms"
	"github.com/pulumi/pulumi-alicloud/sdk/v4/go/alicloud/vpc"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi/config"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		name := "terraform-example"
		if param := cfg.Get("name"); param != "" {
			name = param
		}
		_default, err := vpc.GetNetworks(ctx, &vpc.GetNetworksArgs{
			NameRegex: pulumi.StringRef("^default-NODELETING$"),
		}, nil)
		if err != nil {
			return err
		}
		defaultGetSwitches, err := vpc.GetSwitches(ctx, &vpc.GetSwitchesArgs{
			VpcId:  pulumi.StringRef(_default.Ids[0]),
			ZoneId: pulumi.StringRef("cn-hangzhou-j"),
		}, nil)
		if err != nil {
			return err
		}
		defaultInstance, err := kms.NewInstance(ctx, "default", &kms.InstanceArgs{
			ProductVersion: pulumi.String("3"),
			VpcNum:         pulumi.Int(1),
			KeyNum:         pulumi.Int(1000),
			SecretNum:      pulumi.Int(1000),
			Spec:           pulumi.Int(1000),
			VpcId:          pulumi.String(_default.Ids[0]),
			VswitchIds: pulumi.StringArray{
				pulumi.String(defaultGetSwitches.Ids[0]),
			},
			ZoneIds: pulumi.StringArray{
				pulumi.String("cn-hangzhou-k"),
				pulumi.String("cn-hangzhou-j"),
			},
		})
		if err != nil {
			return err
		}
		defaultKey, err := kms.NewKey(ctx, "default", &kms.KeyArgs{
			DkmsInstanceId:      defaultInstance.ID(),
			PendingWindowInDays: pulumi.Int(7),
		})
		if err != nil {
			return err
		}
		defaultSecret, err := kms.NewSecret(ctx, "default", &kms.SecretArgs{
			SecretData:                 pulumi.String(name),
			SecretName:                 pulumi.String(name),
			VersionId:                  pulumi.String("v1"),
			DkmsInstanceId:             defaultKey.DkmsInstanceId,
			EncryptionKeyId:            defaultKey.ID(),
			ForceDeleteWithoutRecovery: pulumi.Bool(true),
		})
		if err != nil {
			return err
		}
		_, err = apig.NewSecret(ctx, "default", &apig.SecretArgs{
			GatewayType:  pulumi.String("API"),
			Name:         pulumi.String(name),
			SecretSource: pulumi.String("KMS"),
			SecretData:   defaultSecret.SecretData,
			KmsConfig: &apig.SecretKmsConfigArgs{
				KmsInstanceId: defaultSecret.DkmsInstanceId,
				KmsKeyId:      defaultSecret.EncryptionKeyId,
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
