data "alicloud_vpc_enhanced_nat_available_zones" "enhanced" {
}
data "alicloud_ecs_instance_types" "default" {
  availability_zone    = alicloud_vpc_switch.vswitch.zone_id
  cpu_core_count       = 2
  memory_size          = 4
  kubernetes_node_role = "Worker"
  instance_type_family = "ecs.sn1ne"
}

resource "random_integer" "default" {
  lifecycle {
    create_before_destroy = true
  }
  max = 99999
  min = 10000
}
resource "alicloud_vpc_network" "vpc" {
  lifecycle {
    create_before_destroy = true
  }
  description = var.name
  cidr_block  = "192.168.0.0/16"
  vpc_name    = var.name
}
resource "alicloud_vpc_switch" "vswitch" {
  lifecycle {
    create_before_destroy = true
  }
  description  = var.name
  vpc_id       = alicloud_vpc_network.vpc.id
  vswitch_name = var.name
  zone_id      = data.alicloud_vpc_enhanced_nat_available_zones.enhanced.zones[0].zone_id
  cidr_block   = cidrsubnet(alicloud_vpc_network.vpc.cidr_block, 8, 8)
}
resource "alicloud_ecs_snapshot_policy" "default" {
  lifecycle {
    create_before_destroy = true
  }
  name            = var.name
  repeat_weekdays = ["1", "2", "3"]
  retention_days  = -1
  time_points     = ["1", "22", "23"]
}
resource "alicloud_cs_managed_kubernetes" "default" {
  lifecycle {
    create_before_destroy = true
  }
  name               ="terraform-example-${random_integer.default.result}"
  cluster_spec       = "ack.pro.small"
  version            = "1.24.6-aliyun.1"
  new_nat_gateway    = true
  node_cidr_mask     = 26
  proxy_mode         = "ipvs"
  service_cidr       = "172.23.0.0/16"
  pod_cidr           = "10.95.0.0/16"
  worker_vswitch_ids = [alicloud_vpc_switch.vswitch.id]
}
resource "alicloud_ecs_key_pair" "default" {
  lifecycle {
    create_before_destroy = true
  }
  key_pair_name ="terraform-example-${random_integer.default.result}"
}
resource "alicloud_cs_node_pool" "default" {
  lifecycle {
    create_before_destroy = true
  }
  node_pool_name       = "desired_size"
  cluster_id           = alicloud_cs_managed_kubernetes.default.id
  vswitch_ids          = [alicloud_vpc_switch.vswitch.id]
  instance_types       = [data.alicloud_ecs_instance_types.default.instance_types[0].id]
  system_disk_category = "cloud_efficiency"
  system_disk_size     = 40
  key_name             = alicloud_ecs_key_pair.default.key_pair_name
  desired_size         = 2
}
resource "alicloud_arms_environment" "default" {
  lifecycle {
    create_before_destroy = true
  }
  bind_resource_id     = alicloud_cs_node_pool.default.cluster_id
  environment_sub_type = "ManagedKubernetes"
  environment_type     = "CS"
  environment_name     ="terraform-example-${random_integer.default.result}"
}
resource "alicloud_arms_addon_release" "default" {
  lifecycle {
    create_before_destroy = true
  }
  aliyun_lang    = "zh"
  addon_name     = "mysql"
  environment_id = alicloud_arms_environment.default.id
  addon_version  = "0.0.1"
