    }
  }
}

data "alicloud_cen_transit_router_available_resources" "default" {
}
data "alicloud_zones" "defaultGetZones" {
  available_resource_creation = "VSwitch"
}

resource "alicloud_cen_instance" "cen" {
  lifecycle {
    create_before_destroy = true
  }
  description       = "terraform example"
  cen_instance_name = var.name
}
resource "alicloud_cen_transit_router" "tr" {
  lifecycle {
    create_before_destroy = true
  }
  transit_router_name        = var.name
  transit_router_description = "tr-created-by-terraform"
  cen_id                     = alicloud_cen_instance.cen.id
}
resource "alicloud_vpc_network" "vpc1" {
  lifecycle {
    create_before_destroy = true
  }
  description = "created by terraform"
  cidr_block  = "192.168.1.0/24"
  vpc_name    = var.name
}
resource "alicloud_vpc_switch" "vpc1vsw1" {
  lifecycle {
    create_before_destroy = true
  }
  cidr_block   = "192.168.1.0/25"
  vswitch_name = var.name
  vpc_id       = alicloud_vpc_network.vpc1.id
  zone_id      = data.alicloud_cen_transit_router_available_resources.default.resources[0].master_zones[1]
}
resource "alicloud_vpc_switch" "vpc1vsw2" {
  lifecycle {
    create_before_destroy = true
  }
  vpc_id       = alicloud_vpc_network.vpc1.id
  cidr_block   = "192.168.1.128/26"
  vswitch_name = var.name
  zone_id      = data.alicloud_cen_transit_router_available_resources.default.resources[0].master_zones[2]
}
resource "alicloud_vpc_route_table" "foo" {
  lifecycle {
    create_before_destroy = true
  }
  vpc_id           = alicloud_vpc_network.vpc1.id
  route_table_name = var.name
  description      = var.name
}
resource "alicloud_cen_transit_router_vpc_attachment" "tr-vpc1" {
  depends_on = [alicloud_vpc_route_table.foo]
  lifecycle {
    create_before_destroy = true
  }
  zone_mappings {
    vswitch_id = alicloud_vpc_switch.vpc1vsw1.id
    zone_id    = data.alicloud_cen_transit_router_available_resources.default.resources[0].master_zones[1]
  }
  zone_mappings {
    zone_id    = data.alicloud_cen_transit_router_available_resources.default.resources[0].master_zones[2]
    vswitch_id = alicloud_vpc_switch.vpc1vsw2.id
  }
  vpc_id            = alicloud_vpc_network.vpc1.id
  cen_id            = alicloud_cen_instance.cen.id
  transit_router_id = alicloud_cen_transit_router.tr.transit_router_id
}
resource "time_sleep" "wait_10_minutes" {
  depends_on = [alicloud_cen_transit_router_vpc_attachment.tr-vpc1]
