				DiskInfo:    pulumi.String("2x 480GB SATA SSD 4x 3.84TB NVMe SSD"),
				NetworkMode: pulumi.String("net"),
				Name:        pulumi.String("lingjun"),
			},
			ClusterName: pulumi.String(name),
			ClusterDesc: pulumi.String(name),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
