terraform {
  required_providers {
    alicloud = {
      source = "pulumi/alicloud"
    }
  }
}

resource "alicloud_fc_v3_custom_domain" "default" {
  lifecycle {
    create_before_destroy = true
  }
  custom_domain_name = var.name
  route_config = {
    routes = [{
      function_name = var.functionName1
      rewrite_config = {
        regex_rules = [{
          match       = "/api/*"
          replacement = "$1"
          }, {
          match       = "/api1/*"
          replacement = "$1"
          }, {
          match       = "/api2/*"
          replacement = "$1"
        }]
        wildcard_rules = [{
          match       = "^/api1/.+?/(.*)"
          replacement = "/api/v1/$1"
          }, {
          match       = "^/api2/.+?/(.*)"
          replacement = "/api/v2/$1"
          }, {
          match       = "^/api2/.+?/(.*)"
          replacement = "/api/v3/$1"
        }]
        equal_rules = [{
          match       = "/old"
          replacement = "/new"
          }, {
          replacement = "/new1"
          match       = "/old1"
          }, {
          match       = "/old2"
          replacement = "/new2"
        }]
      }
      methods   = ["GET", "POST", "DELETE", "HEAD"]
      path      = "/a"
      qualifier = "LATEST"
      }, {
      function_name = var.functionName1
      methods       = ["GET"]
      path          = "/b"
      qualifier     = "LATEST"
      }, {
      function_name = var.functionName1
      methods       = ["POST"]
      path          = "/c"
      qualifier     = "1"
    }]
