            .description(name)
            .vpcId(defaultX7MgJO.id())
            .zoneId(zoneId)
            .cidrBlock("10.0.0.0/24")
            .build());

        var defaultQpsLKr = new Instance("defaultQpsLKr", InstanceArgs.builder()
            .paymentType("PayAsYouGo")
            .tableEngineNodeCount(2)
            .instanceStorage("80")
