DualStack Usage


<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as alicloud from "@pulumi/alicloud";

const config = new pulumi.Config();
const name = config.get("name") || "tf-example";
const zone = config.getObject<any>("zone") || [
    "cn-beijing-i",
    "cn-beijing-k",
    "cn-beijing-l",
];
const vpc = new alicloud.vpc.Network("vpc", {
    vpcName: name,
    cidrBlock: "10.2.0.0/16",
    enableIpv6: true,
});
const vsw: alicloud.vpc.Switch[] = [];
for (let range = 0; range < 2; range++) {
    vsw.push(new alicloud.vpc.Switch(`vsw-${range}`, {
        enableIpv6: true,
        ipv6CidrBlockMask: Number(`1${range}`),
        vswitchName: `vsw-${range}-for-nlb`,
        vpcId: vpc.id,
        cidrBlock: `10.2.1${range}.0/24`,
        zoneId: zone[range],
    }));
}
const _default = new alicloud.vpc.Ipv6Gateway("default", {
    ipv6GatewayName: name,
    vpcId: vpc.id,
});
const nlb = new alicloud.nlb.LoadBalancer("nlb", {
    loadBalancerName: name,
    loadBalancerType: "Network",
    addressType: "Intranet",
    addressIpVersion: "DualStack",
    ipv6AddressType: "Internet",
    vpcId: vpc.id,
    crossZoneEnabled: false,
    tags: {
        Created: "TF",
        For: "example",
    },
    zoneMappings: [
        {
            vswitchId: vsw[0].id,
            zoneId: zone[0],
        },
        {
            vswitchId: vsw[1].id,
            zoneId: zone[1],
        },
    ],
}, {
    dependsOn: [_default],
});
