		if err != nil {
			return err
		}
		defaultDbNode, err := rds.NewDbNode(ctx, "default", &rds.DbNodeArgs{
			DbInstanceId: defaultInstance.ID(),
			ClassCode:    defaultInstance.InstanceType,
			ZoneId:       defaultSwitch.ZoneId,
