func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		name := "terraform-example"
		if param := cfg.Get("name"); param != "" {
			name = param
		}
		_default, err := oss.GetBuckets(ctx, &oss.GetBucketsArgs{}, nil)
		if err != nil {
			return err
		}
		defaultNetwork, err := vpc.NewNetwork(ctx, "default", &vpc.NetworkArgs{
			IsDefault: pulumi.Bool(false),
			CidrBlock: pulumi.String("172.16.0.0/16"),
			VpcName:   pulumi.String(name),
		})
		if err != nil {
			return err
		}
		defaultSwitch, err := vpc.NewSwitch(ctx, "default", &vpc.SwitchArgs{
			IsDefault:   pulumi.Bool(false),
			VpcId:       defaultNetwork.ID(),
			ZoneId:      pulumi.String("cn-hangzhou-i"),
			CidrBlock:   pulumi.String("172.16.0.0/24"),
			VswitchName: pulumi.String(name),
		})
		if err != nil {
			return err
		}
		defaultUser, err := ram.NewUser(ctx, "default", &ram.UserArgs{
			Name:        pulumi.String(name),
			DisplayName: pulumi.String("displayname"),
			Mobile:      pulumi.String("86-18888888888"),
			Email:       pulumi.String("hello.uuu@aaa.com"),
			Comments:    pulumi.String("yoyoyo"),
		})
		if err != nil {
			return err
		}
		defaultVvpInstance, err := realtimecompute.NewVvpInstance(ctx, "default", &realtimecompute.VvpInstanceArgs{
			VvpInstanceName: pulumi.String(name),
			Storage: &realtimecompute.VvpInstanceStorageArgs{
				Oss: &realtimecompute.VvpInstanceStorageOssArgs{
					Bucket: pulumi.String(_default.Buckets[0].Name),
				},
			},
			VpcId: defaultNetwork.ID(),
			VswitchIds: pulumi.StringArray{
				defaultSwitch.ID(),
			},
			ResourceSpec: &realtimecompute.VvpInstanceResourceSpecArgs{
				Cpu:      pulumi.Int(8),
				MemoryGb: pulumi.Int(32),
			},
			PaymentType: pulumi.String("PayAsYouGo"),
			ZoneId:      defaultSwitch.ZoneId,
		})
		if err != nil {
			return err
		}
		_, err = realtimecompute.NewMember(ctx, "default", &realtimecompute.MemberArgs{
			Member: defaultUser.ID(),
			Namespace: defaultVvpInstance.VvpInstanceName.ApplyT(func(vvpInstanceName string) (string, error) {
				return fmt.Sprintf("%v-default", vvpInstanceName), nil
			}).(pulumi.StringOutput),
			ResourceId: defaultVvpInstance.ResourceId,
			Role:       pulumi.String("viewer"),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
