terraform {
  required_providers {
    alicloud = {
      source = "pulumi/alicloud"
    }
  }
}

data "alicloud_resourcemanager_resource_groups" "default" {
  status = "OK"
}
data "alicloud_zones" "defaultGetZones" {
  available_instance_type = "ecs.g7.xlarge"
}
data "alicloud_emrv2_cluster_instances" "ids" {
}
data "alicloud_emrv2_cluster_instances" "nodeGroupNames" {
  node_group_names = ["emr-core"]
}

resource "alicloud_vpc_network" "default" {
  lifecycle {
    create_before_destroy = true
  }
  vpc_name   = "TF-VPC"
  cidr_block = "172.16.0.0/12"
}
resource "alicloud_vpc_switch" "default" {
  lifecycle {
    create_before_destroy = true
  }
  vpc_id       = alicloud_vpc_network.default.id
  cidr_block   = "172.16.0.0/21"
  zone_id      = data.alicloud_zones.defaultGetZones.zones[0].id
  vswitch_name = "TF_VSwitch"
}
resource "alicloud_ecs_ecs_key_pair" "default" {
  lifecycle {
    create_before_destroy = true
  }
  key_pair_name = "terraform-kp"
}
resource "alicloud_ecs_security_group" "default" {
  lifecycle {
    create_before_destroy = true
  }
  name   = "TF_SECURITY_GROUP"
  vpc_id = alicloud_vpc_network.default.id
}
resource "alicloud_ram_role" "default" {
  lifecycle {
    create_before_destroy = true
  }
  name        = "emrtf"
  document    = <<EOF
    {
        \"Statement\": [
        {
            \"Action\": \"sts:AssumeRole\",
            \"Effect\": \"Allow\",
            \"Principal\": {
            \"Service\": [
                \"emr.aliyuncs.com\",
                \"ecs.aliyuncs.com\"
            ]
            }
        }
        ],
        \"Version\": \"1\"
    }
EOF

  description = "this is a role test."
  force       = true
}
resource "alicloud_emrv2_cluster" "default" {
  lifecycle {
    create_before_destroy = true
  }
  payment_type    = "PayAsYouGo"
  cluster_type    = "DATALAKE"
  release_version = "EMR-5.10.0"
  cluster_name    = "terraform-emr-cluster-v2"
  deploy_mode     = "NORMAL"
  security_mode   = "NORMAL"
  applications    = ["HADOOP-COMMON", "HDFS", "YARN", "HIVE", "SPARK3", "TEZ"]
  application_configs {
    application_name  = "HIVE"
    config_file_name  = "hivemetastore-site.xml"
    config_item_key   = "hive.metastore.type"
    config_item_value = "DLF"
    config_scope      = "CLUSTER"
  }
  application_configs {
    application_name  = "SPARK3"
    config_file_name  = "hive-site.xml"
    config_item_key   = "hive.metastore.type"
    config_item_value = "DLF"
    config_scope      = "CLUSTER"
  }
  node_attributes {
    ram_role          = alicloud_ram_role.default.name
    security_group_id = alicloud_ecs_security_group.default.id
    vpc_id            = alicloud_vpc_network.default.id
    zone_id           = data.alicloud_zones.defaultGetZones.zones[0].id
    key_pair_name     = alicloud_ecs_ecs_key_pair.default.id
  }
  tags = {
    "created" = "tf"
  }
  node_groups {
    node_group_type = "MASTER"
    node_group_name = "emr-master"
    payment_type    = "PayAsYouGo"
    vswitch_ids     = [alicloud_vpc_switch.default.id]
    with_public_ip  = false
    instance_types  = ["ecs.g7.xlarge"]
    node_count      = 1
