alicloud:polardb/getAccounts:getAccounts.description:
The <span pulumi-lang-nodejs="`alicloud.polardb.getAccounts`" pulumi-lang-dotnet="`alicloud.polardb.getAccounts`" pulumi-lang-go="`polardb.getAccounts`" pulumi-lang-python="`polardb_get_accounts`" pulumi-lang-yaml="`alicloud.polardb.getAccounts`" pulumi-lang-java="`alicloud.polardb.getAccounts`" pulumi-lang-hcl="`data.alicloud_polardb_accounts`">`alicloud.polardb.getAccounts`</span> data source provides a collection of PolarDB cluster database account available in Alibaba Cloud account.
Filters support regular expression for the account name, searches by clusterId.

> **NOTE:** Available since v1.70.0+.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as alicloud from "@pulumi/alicloud";

export = async () => {
    const _this = await alicloud.polardb.getNodeClasses({
        dbType: "MySQL",
        dbVersion: "8.0",
        payType: "PostPaid",
        category: "Normal",
    });
    const defaultNetwork = new alicloud.vpc.Network("default", {
        vpcName: "terraform-example",
        cidrBlock: "172.16.0.0/16",
    });
    const defaultSwitch = new alicloud.vpc.Switch("default", {
        vpcId: defaultNetwork.id,
        cidrBlock: "172.16.0.0/24",
        zoneId: _this.classes?.[0]?.zoneId,
        vswitchName: "terraform-example",
    });
    const cluster = new alicloud.polardb.Cluster("cluster", {
        dbType: "MySQL",
        dbVersion: "8.0",
        payType: "PostPaid",
        dbNodeCount: 2,
        dbNodeClass: _this.classes?.[0]?.supportedEngines?.[0]?.availableResources?.[0]?.dbNodeClass,
        vswitchId: defaultSwitch.id,
    });
    const polardbClustersDs = alicloud.polardb.getClustersOutput({
        descriptionRegex: cluster.description,
        status: "Running",
    });
