    comments: "yoyoyo",
});
const defaultVvpInstance = new alicloud.realtimecompute.VvpInstance("default", {
    vvpInstanceName: name,
    storage: {
        oss: {
            bucket: _default.then(_default => _default.buckets?.[0]?.name),
        },
